-- Mountain Social Adventure performance guard v2.7
local Players=game:GetService('Players');local RunService=game:GetService('RunService');local Lighting=game:GetService('Lighting')
local player=Players.LocalPlayer;local samples={};local elapsed=0;local low=false
local function avg()local t=0;for _,v in ipairs(samples)do t+=v end;return #samples>0 and t/#samples or 60 end
local function mode(on)if on==low then return end;low=on;player:SetAttribute('ACC_LowFX',on);local at=Lighting:FindFirstChildOfClass('Atmosphere');if at and on then at.Glare=math.min(at.Glare,.04) end;for _,o in ipairs(workspace:GetDescendants())do if o:IsA('ParticleEmitter') then local base=o:GetAttribute('ACC_BaseRate');if base==nil then o:SetAttribute('ACC_BaseRate',o.Rate);base=o.Rate end;o.Rate=on and math.floor(base*.35) or base elseif o:IsA('PointLight') and o.Name~='SummitBeacon' then local b=o:GetAttribute('ACC_BaseBrightness');if b==nil then o:SetAttribute('ACC_BaseBrightness',o.Brightness);b=o.Brightness end;o.Brightness=on and b*.65 or b end end end
